if(!exists('lgd_backtest',mode='function'))library(creditratingsystem)
close<-function(a,b,tol=1e-11)stopifnot(max(abs(unlist(a)-unlist(b)))<tol);reject<-function(expr,code){e<-tryCatch(force(expr),error=identity);stopifnot(inherits(e,'error'),identical(e$code,code))}
d<-list(model_id='frozen',model_version='1',parameter_version='1',data_fingerprint='synthetic-workouts',population_id='defaulted-loans',split_id='holdout',prediction_origin='HOLDOUT',evaluation_cutoff='2024-01-01',target=list(event='default',horizon=30,time_unit='days',probability_measure='PHYSICAL',conditioning='default'),currency='EUR')
rows<-lapply(0:2,function(i)list(prediction_id=as.character(i),entity_id=paste0('e',i),cluster_id=paste0('g',i),segment='all',as_of='2020-01-01',forecast_known_at='2020-01-01',horizon_end='2020-01-31',model_id='frozen',model_version='1',parameter_version='1',default_date='2020-01-15',outcome_known_at='2021-01-01',workout_closed_at=if(i==2)NULL else'2020-12-31',workout_status=if(i==2)'OPEN'else'CLOSED',predicted_lgd=c(.4,.6,.1)[i+1],realized_lgd=if(i==2)NULL else c(.2,.8)[i+1],ead_at_default=c(100,300,100)[i+1]))
r<-lgd_backtest(rows,d,list(method='closed_only',reference='closed descriptive cohort'),'cluster_bootstrap',list(c('g0','g0','g2'),c('g1','g1','g2'),c('g0','g1','g2')),confidence_level=.8)$value;m<-r$metrics$overall;close(m$count_weighted$bias,0);close(m$ead_weighted$bias,-.1);close(m$ead_weighted$mae,.2);close(m$ead_weighted$rmse,.2);close(sum(unlist(m$ead_weighted$bias_contributions)),-.1);stopifnot(r$coverage$included_count==2,r$coverage$exclusion_counts$OPEN_WORKOUT==1);close(r$uncertainty$intervals$count_weighted.bias$lower,-.16);close(r$uncertainty$intervals$count_weighted.bias$upper,.16)
rows[[3]]$realized_lgd<--10000;stopifnot(identical(lgd_backtest(rows,d,list(method='closed_only',reference='closed'),'none')$value$metrics,r$metrics))
policy<-list(method='ipcw',reference='supplied train-only completion model',identification='closure_independent_of_final_lgd_given_recorded_covariates',model_fingerprint='frozen-selection',model_known_at='2019-01-01',minimum_observation_probability=.05);for(i in seq_along(rows))rows[[i]]$observation_probability<-c(.5,1,.5)[i];r<-lgd_backtest(rows,d,policy,'cluster_bootstrap',list(c('g0','g1','g2'),c('g2','g2','g2')))$value;close(r$metrics$overall$count_weighted$bias,.2/3);stopifnot(is.null(r$uncertainty$intervals$count_weighted.bias$lower));bad<-d;bad$evaluation_cutoff<-'2020-01-20';stopifnot(lgd_backtest(rows,bad,policy,'none')$value$applicability=='NOT_APPLICABLE')
values<-rbind(c(100,120,50,150),c(90,100,100,100),c(110,120,120,100));for(i in seq_along(rows)){rows[[i]]$predicted_ead<-values[i,1];rows[[i]]$realized_ead<-values[i,2];rows[[i]]$drawn_at_reference<-values[i,3];rows[[i]]$limit_at_reference<-values[i,4];rows[[i]]$realized_ead_date<-'2020-01-15';rows[[i]]$currency<-'EUR'};r<-ead_backtest(rows,d,list(method='reference_limit',reference='frozen facility limits'),'none')$value;m<-r$metrics$ead$overall$selected_weighting;close(m$bias,-100/7);close(sum(unlist(m$bias_contributions)),m$bias);stopifnot(r$diagnostics$ccf_undefined_count==2);close(r$diagnostics$denominators[[1]]$observed_ccf,.7);stopifnot(is.null(r$diagnostics$denominators[[2]]$observed_ccf));close(r$metrics$ccf$overall$unweighted$bias,-.2);rows[[1]]$realized_ead_date<-'2020-01-16';reject(ead_backtest(rows,d,list(method='equal',reference='count'),'none'),'VALIDATION_EAD_DATE')
stopifnot(lgd_backtest(list(),d,list(method='closed_only',reference='empty'),'none')$value$applicability=='NOT_APPLICABLE')
